import config from '../config';

const DEFAULT_TIMEOUT = 15000;

function getBaseUrl() {
  const app = getApp();
  const fromGlobal = app && app.globalData && app.globalData.apiBaseUrl;
  if (fromGlobal) return fromGlobal;
  if (!config.useLocalDevApi && config.productionApiBase) {
    return String(config.productionApiBase).replace(/\/+$/, '');
  }
  return `http://127.0.0.1:${config.devPort}`;
}

export function buildUrl(path, query) {
  const base = getBaseUrl().replace(/\/+$/, '');
  const p = String(path || '').replace(/^\/+/, '');
  const qs =
    query && typeof query === 'object'
      ? Object.keys(query)
          .filter((k) => query[k] !== undefined && query[k] !== null && query[k] !== '')
          .map((k) => `${encodeURIComponent(k)}=${encodeURIComponent(String(query[k]))}`)
          .join('&')
      : '';
  return `${base}/${p}${qs ? `?${qs}` : ''}`;
}

/** 去掉首尾空白，并避免本地误存成「Bearer xxx」导致双重 Bearer */
function normalizeAccessToken(raw) {
  if (raw == null || raw === '') return '';
  let t = String(raw).trim();
  if (/^bearer\s+/i.test(t)) t = t.replace(/^bearer\s+/i, '').trim();
  return t;
}

export function getToken() {
  try {
    return normalizeAccessToken(wx.getStorageSync('access_token'));
  } catch (e) {
    return '';
  }
}

export function request({ method = 'GET', path, query, data, auth = true, timeout = DEFAULT_TIMEOUT } = {}) {
  const header = { 'content-type': 'application/json' };
  if (auth) {
    const token = getToken();
    if (token) header.Authorization = `Bearer ${token}`;
  }
  const url = buildUrl(path, query);

  // 让“是否真正发出请求”在控制台可见（开发调试用）
  try {
    console.log('[http.request]', {
      method,
      url,
      auth,
      hasToken: Boolean(header.Authorization),
      timeout,
    });
  } catch (e) {
    /* ignore */
  }

  return new Promise((resolve, reject) => {
    wx.request({
      url,
      method,
      data,
      timeout,
      header,
      success: (res) => {
        try {
          console.log('[http.response]', { url, statusCode: res.statusCode, data: res.data });
        } catch (e) {
          /* ignore */
        }
        const code = res.statusCode;
        if (code != null && code >= 400) {
          const data = res.data && typeof res.data === 'object' ? res.data : {};
          const msg =
            data.message || data.hint || (typeof res.data === 'string' ? res.data : '') || `HTTP ${code}`;
          const err = new Error(msg);
          err.statusCode = code;
          err.body = data;
          reject(err);
          return;
        }
        resolve(res.data);
      },
      fail: (err) => {
        try {
          console.warn('[http.fail]', { url, err });
        } catch (e) {
          /* ignore */
        }
        reject(err);
      },
    });
  });
}

// app.js
import config from './config';
import createBus from './utils/eventBus';
import { readStoredModuleTabs, STORAGE_KEY } from './utils/moduleEntryGuard';
import { request as httpRequest } from './api/http';
import { cacheGet, cacheSet } from './utils/persistCache';

const PHONE_AUTHORIZED_LOGIN_KEY = 'phone_authorized_login_v1';
const WECHAT_AUTHORIZED_LOGIN_KEY = 'wechat_authorized_login_v2';
const LEGACY_WECHAT_AUTHORIZED_LOGIN_KEY = 'wechat_authorized_login';

function normalizeUserInfo(user) {
  if (!user) return null;
  const avatar = user.avatar || user.avatarUrl || user.image || '';
  return {
    ...user,
    nickName: user.nickName || user.name || '',
    avatar,
    avatarUrl: user.avatarUrl || avatar,
  };
}

function isFreshLoginCode(ticket) {
  return Boolean(ticket && ticket.code && Date.now() - ticket.createdAt < 4 * 60 * 1000);
}

App({
  async onLaunch() {
    console.log('>>> onLaunch 开始执行');
    const storedTabs = readStoredModuleTabs();
    this.globalData.moduleEntryTabs = storedTabs && Array.isArray(storedTabs.tabs) ? storedTabs.tabs : null;

    // 仅本地/测试环境主动开启微信内置调试面板，正式版不触发该 API。
    if (config.enableVConsole) {
      try {
        wx.setEnableDebug({ enableDebug: true });
      } catch (e) {
        /* ignore */
      }
    }

    let apiBase;
    if (config.useLocalDevApi) {
      apiBase = `http://${config.devLanHost}:${config.devPort}`;
      try {
        if (wx.getSystemInfoSync().platform === 'devtools') {
          apiBase = `http://127.0.0.1:${config.devPort}`;
        }
      } catch (e) {
        /* ignore */
      }
    } else {
      apiBase = String(config.productionApiBase || '').replace(/\/+$/, '');
    }
    this.globalData.apiBaseUrl = apiBase;
    this.globalData.offlineMode = false;

    // 先读取本地缓存的用户信息（离线 B1 用）
    const cachedMe = cacheGet('offline_cache_user_me');
    if (cachedMe) this.globalData.userInfo = normalizeUserInfo(cachedMe);

    const updateManager = wx.getUpdateManager();
    updateManager.onCheckForUpdate(() => {});
    updateManager.onUpdateReady(() => {
      wx.showModal({
        title: '更新提示',
        content: '新版本已经准备好，是否重启应用？',
        success(res) {
          if (res.confirm) updateManager.applyUpdate();
        },
      });
    });

    // 启动自检：先打一下 health，确认小程序侧能否发出 HTTP 请求（开发调试用）
    try {
      await httpRequest({ method: 'GET', path: 'api/health', auth: false });
    } catch (e) {
      console.warn('启动自检：health 请求失败', e);
    }

    await this.syncModuleEntryTabsFromApi();
  },

  onShow() {
    // 自建后端：后续可在此同步配置
  },

  /** 自建后端：拉取 Tab 入口配置并覆盖本地缓存 */
  async syncModuleEntryTabsFromApi() {
    console.log('>>> syncModuleEntryTabsFromApi 开始执行');
    try {
      const res = await httpRequest({
        method: 'GET',
        path: 'api/app-settings/module-entry-tabs',
        auth: false,
      });
      if (res && res.code === 200 && res.data && Array.isArray(res.data.tabs)) {
        this.globalData.moduleEntryTabs = res.data.tabs;
        try {
          wx.setStorageSync(STORAGE_KEY, { tabs: this.globalData.moduleEntryTabs });
        } catch (e) {
          /* ignore */
        }
        this.eventBus.emit('moduleEntryVisibilityChange');
      }
    } catch (err) {
      console.warn('同步模块入口配置失败，使用本地缓存或默认0', err);
    }
  },

  /** 运行时更新 Tab 入口配置（写入本地缓存，覆盖云端/本地默认值） */
  setModuleEntryTabs(tabs) {
    this.globalData.moduleEntryTabs = Array.isArray(tabs) ? tabs : this.globalData.moduleEntryTabs;
    try {
      wx.setStorageSync(STORAGE_KEY, { tabs: this.globalData.moduleEntryTabs });
    } catch (e) {
      /* ignore */
    }
    this.eventBus.emit('moduleEntryVisibilityChange');
  },

  async login() {
    try {
      // 每次启动都用最新登录态覆盖旧 token，避免旧 token 导致后续接口持续 401
      try {
        wx.removeStorageSync('access_token');
        wx.removeStorageSync(PHONE_AUTHORIZED_LOGIN_KEY);
        wx.removeStorageSync(WECHAT_AUTHORIZED_LOGIN_KEY);
        wx.removeStorageSync(LEGACY_WECHAT_AUTHORIZED_LOGIN_KEY);
      } catch (e) {
        /* ignore */
      }
      const loginRes = await new Promise((resolve, reject) => {
        wx.login({
          timeout: 10000,
          success: resolve,
          fail: reject,
        });
      });
      const code = loginRes && loginRes.code;
      if (!code) throw new Error('wx.login 未返回 code');

      const res = await httpRequest({
        method: 'POST',
        path: 'api/auth/wechat/login',
        data: { code },
        auth: false,
      });

      if (!res || !res.token) {
        console.warn('>>> login 失败: 后端未返回 token', res);
        throw new Error((res && res.message) || '后端登录失败');
      }

      wx.setStorageSync('access_token', res.token);

      this.globalData.userInfo = normalizeUserInfo(res.user);
      this.globalData.openid = (res.user && res.user.openid) || '';
      this.globalData.offlineMode = false;
      if (this.globalData.userInfo) cacheSet('offline_cache_user_me', this.globalData.userInfo, 7 * 24 * 3600);
      console.log('>>> login 成功, token:', res.token ? '已设置' : '无');
    } catch (err) {
      console.warn('>>> 自建后端登录失败，进入离线模式', err);
      // 登录失败时清理 token，避免携带无效 token 继续请求导致 token_invalid
      try {
        wx.removeStorageSync('access_token');
        wx.removeStorageSync(PHONE_AUTHORIZED_LOGIN_KEY);
        wx.removeStorageSync(WECHAT_AUTHORIZED_LOGIN_KEY);
        wx.removeStorageSync(LEGACY_WECHAT_AUTHORIZED_LOGIN_KEY);
      } catch (e) {
        /* ignore */
      }
      this.globalData.offlineMode = true;
      // 离线模式：尽量用缓存用户信息
      const cachedMe = cacheGet('offline_cache_user_me');
      if (cachedMe) this.globalData.userInfo = normalizeUserInfo(cachedMe);
    }
  },

  async phoneLogin(phoneCode) {
    const code = String(phoneCode || '').trim();
    if (!code) throw new Error('未获取到手机号授权凭证');

    try {
      wx.removeStorageSync('access_token');
      wx.removeStorageSync(PHONE_AUTHORIZED_LOGIN_KEY);
      wx.removeStorageSync(WECHAT_AUTHORIZED_LOGIN_KEY);
      wx.removeStorageSync(LEGACY_WECHAT_AUTHORIZED_LOGIN_KEY);
    } catch (e) {
      /* ignore */
    }

    const jsCode = await this.getLoginCode();
    if (!jsCode) throw new Error('wx.login 未返回 code');
    try {
      const account = wx.getAccountInfoSync ? wx.getAccountInfoSync() : {};
      const miniProgram = account && account.miniProgram ? account.miniProgram : {};
      console.info('[phoneLogin] miniProgram appId:', miniProgram.appId || '');
    } catch (e) {
      /* ignore */
    }

    const res = await httpRequest({
      method: 'POST',
      path: 'api/auth/wechat/phone-login',
      data: { code: jsCode, phoneCode: code },
      auth: false,
    });

    if (!res || !res.token) {
      throw new Error((res && res.message) || '手机号登录失败');
    }

    wx.setStorageSync('access_token', res.token);
    wx.setStorageSync(PHONE_AUTHORIZED_LOGIN_KEY, true);
    this.globalData.userInfo = normalizeUserInfo(res.user);
    this.globalData.openid = (res.user && res.user.openid) || '';
    this.globalData.offlineMode = false;
    if (this.globalData.userInfo) cacheSet('offline_cache_user_me', this.globalData.userInfo, 7 * 24 * 3600);
    await this.syncModuleEntryTabsFromApi();
    this.eventBus.emit('userInfoChange');
    return res;
  },

  async refreshLoginCode() {
    const loginRes = await new Promise((resolve, reject) => {
      wx.login({
        timeout: 10000,
        success: resolve,
        fail: reject,
      });
    });
    const code = loginRes && loginRes.code;
    if (!code) throw new Error('wx.login 未返回 code');
    this.globalData.loginCodeTicket = { code, createdAt: Date.now() };
    return code;
  },

  async getLoginCode() {
    const ticket = this.globalData.loginCodeTicket;
    if (isFreshLoginCode(ticket)) {
      this.globalData.loginCodeTicket = null;
      return ticket.code;
    }
    return this.refreshLoginCode();
  },

  globalData: {
    userInfo: null,
    userId: 'user1', // 任务/商城等模块当前用户，Mock 用
    openid: '',
    useCloudBase: false,
    offlineMode: false,
    apiBaseUrl: '',
    loginCodeTicket: null,
    moduleEntryTabs: null,
    /** 底部自定义 TabBar 当前选中 key，与 tab 页路由同步（跨页面组件实例共享） */
    tabBarSelectedKey: '',
  },

  /** 全局事件总线 */
  eventBus: createBus(),
});

import { buildVisibleTabBarList } from '~/utils/moduleEntryGuard';

Component({
  data: {
    value: '',
    visibleList: [],
  },
  lifetimes: {
    attached() {
      const app = getApp();
      this._onVisibilityChange = () => this.refreshTabBar();
      app.eventBus.on('moduleEntryVisibilityChange', this._onVisibilityChange);
      this.refreshTabBar();
    },
    detached() {
      getApp().eventBus.off('moduleEntryVisibilityChange', this._onVisibilityChange);
    },
  },
  pageLifetimes: {
    show() {
      this.refreshTabBar();
    },
  },
  methods: {
    /** 供 Tab 页 onShow 调用：getTabBar().syncFromRoute() */
    syncFromRoute() {
      this.refreshTabBar();
    },
    refreshTabBar() {
      const app = getApp();
      const visibleList = buildVisibleTabBarList();
      const pages = getCurrentPages();
      const curPage = pages[pages.length - 1];
      let value = '';
      if (curPage && curPage.route) {
        const nameRe = /pages\/(\w+)\/index/.exec(curPage.route);
        if (nameRe && nameRe[1]) value = nameRe[1];
      }
      let allowed = visibleList.some((item) => item.value === value);
      if (!allowed && app.globalData.tabBarSelectedKey) {
        value = app.globalData.tabBarSelectedKey;
        allowed = visibleList.some((item) => item.value === value);
      }
      if (!allowed) {
        value = visibleList[0] ? visibleList[0].value : '';
      }
      if (value) {
        app.globalData.tabBarSelectedKey = value;
      }
      this.setData({ visibleList, value });
    },
    handleChange(e) {
      const { value } = e.detail;
      const app = getApp();
      app.globalData.tabBarSelectedKey = value;
      // 避免与 wx.switchTab 同时 setData 导致 TDesign TabBar 高亮异常：仅 switchTab，选中态由目标页 onShow + syncFromRoute 刷新
      wx.switchTab({ url: `/pages/${value}/index` });
    },
  },
});

import { commonAPI } from '~/api/cloud';

Page({
  data: {
    feedbackType: '',
    typeOptions: [
      { label: '功能建议', value: 'suggestion' },
      { label: '问题反馈', value: 'bug' },
      { label: '其他', value: 'other' },
    ],
    content: '',
    contact: '',
    submitting: false,
  },

  onTypeChange(e) {
    const { value } = e.detail;
    const selected = this.data.typeOptions.find((item) => item.value === value);
    this.setData({
      feedbackType: value,
      typeLabel: selected?.label || '',
    });
  },

  onContentInput(e) {
    this.setData({ content: e.detail.value });
  },

  onContactInput(e) {
    this.setData({ contact: e.detail.value });
  },

  async submit() {
    const { feedbackType, content, contact } = this.data;

    if (!feedbackType) {
      wx.showToast({ title: '请选择反馈类型', icon: 'none' });
      return;
    }

    if (!content.trim()) {
      wx.showToast({ title: '请输入反馈内容', icon: 'none' });
      return;
    }

    if (!contact.trim()) {
      wx.showToast({ title: '请输入联系方式', icon: 'none' });
      return;
    }

    this.setData({ submitting: true });

    try {
      const res = await commonAPI.submitFeedback({
        type: feedbackType,
        content: content.trim(),
        contact: contact.trim(),
      });

      this.setData({ submitting: false });

      if (res.code === 200) {
        wx.showToast({
          title: '提交成功，感谢您的反馈！',
          icon: 'success',
          duration: 2000,
        });

        setTimeout(() => {
          wx.navigateBack();
        }, 1500);
      } else {
        wx.showToast({
          title: res.message || '提交失败，请重试',
          icon: 'none',
        });
      }
    } catch (err) {
      this.setData({ submitting: false });
      wx.showToast({
        title: '提交失败，请重试',
        icon: 'none',
      });
    }
  },
});

/**
 * 接口结果内存缓存，用于减少重复请求、优化性能
 * TTL 单位：秒
 */
const store = {};

function keyFrom(name, data) {
  try {
    return name + '_' + JSON.stringify(data || {});
  } catch {
    return name + '_' + String(data);
  }
}

export function get(name, data) {
  const key = keyFrom(name, data);
  const item = store[key];
  if (!item) return null;
  if (item.expireAt && Date.now() > item.expireAt) {
    delete store[key];
    return null;
  }
  return item.data;
}

export function set(name, data, payload, ttlSeconds = 60) {
  const key = keyFrom(name, data);
  store[key] = {
    data: payload,
    expireAt: ttlSeconds ? Date.now() + ttlSeconds * 1000 : 0,
  };
}

export function remove(name, data) {
  const key = keyFrom(name, data);
  delete store[key];
}

export function clear() {
  Object.keys(store).forEach((k) => delete store[k]);
}

/** 清除某个云函数名对应的全部缓存（用于发布/删除后列表立即刷新） */
export function invalidateCloudFunction(functionName) {
  if (!functionName) return;
  const prefix = String(functionName) + '_';
  Object.keys(store).forEach((k) => {
    if (k.startsWith(prefix)) delete store[k];
  });
}

export default { get, set, remove, clear, invalidateCloudFunction };

/** 论坛帖子列表：图/视频槽位（最多 3 格，优先图片，未满则展示首个视频） */

function buildListMediaSlots(images, videos) {
  const slots = [];
  for (let i = 0; i < images.length && slots.length < 3; i += 1) {
    slots.push({ type: 'image', url: images[i] });
  }
  if (videos.length > 0 && slots.length < 3) {
    slots.push({ type: 'video', url: videos[0] });
  }
  const imageInSlots = slots.filter((s) => s.type === 'image').length;
  const moreCount =
    Math.max(0, images.length - imageInSlots) +
    Math.max(0, videos.length - (slots.some((s) => s.type === 'video') ? 1 : 0));
  const listMediaMoreLabel = moreCount > 0 ? (moreCount > 9 ? '9+' : `+${moreCount}`) : '';
  return { slots, listMediaMoreLabel };
}

export function normalizeForumListPost(p) {
  if (!p) return p;
  const images = Array.isArray(p.images) ? p.images : [];
  const videos = Array.isArray(p.videos) ? p.videos : [];
  const { slots, listMediaMoreLabel } = buildListMediaSlots(images, videos);
  return {
    ...p,
    images,
    videos,
    listMediaSlots: slots,
    listMediaMoreLabel,
  };
}

/** 是否含图/视频（用于关闭虚拟列表等） */
export function forumListPostHasMedia(p) {
  if (!p) return false;
  const images = Array.isArray(p.images) ? p.images : [];
  const videos = Array.isArray(p.videos) ? p.videos : [];
  return images.length > 0 || videos.length > 0;
}

import { decryptText } from '~/utils/textCipher';

const STORAGE_KEY = 'module_entry_tabs';

/** 与 app.json tabBar 顺序一致，用于「第一个可见 Tab」 */
const TAB_ORDER = ['task', 'errand', 'forum', 'mall', 'my'];
/** 可配置模块（含非底部 Tab 模块） */
const MODULE_ORDER = ['task', 'errand', 'forum', 'mall', 'my'];
const DEFAULT_TAB_LIST = [
  { key: 'task', label: '业主互助', icon: 'root-list', enabled: true },
  { key: 'errand', label: '小区跑腿', icon: 'service', enabled: true },
  { key: 'forum', label: '小区留言', icon: 'chat', enabled: true },
  { key: 'mall', label: '小区市场', icon: 'shop', enabled: true },
  { key: 'my', label: '我的', icon: 'user', enabled: true, always: true },
];

function normalizeTabs(rawTabs) {
  const base = Array.isArray(rawTabs) ? rawTabs : [];
  const seen = new Set();
  const tabs = [];

  for (const t of base) {
    if (!t || typeof t !== 'object') continue;
    const key = t.key;
    if (!key || typeof key !== 'string') continue;
    if (!MODULE_ORDER.includes(key)) continue;
    if (seen.has(key)) continue;
    seen.add(key);
    tabs.push({
      key,
      value: key,
      label: typeof t.labelEnc === 'string' && t.labelEnc ? decryptText(t.labelEnc) : (typeof t.label === 'string' && t.label ? t.label : key),
      icon: typeof t.icon === 'string' && t.icon ? t.icon : '',
      enabled: t.enabled !== false,
      always: t.always === true,
    });
  }

  return tabs;
}

export function getModuleEntryTabs() {
  const app = getApp();
  const tabs = app.globalData.moduleEntryTabs;
  if (Array.isArray(tabs)) return normalizeTabs(tabs);
  // 未加载到配置（也没有缓存）时仍保留应用内置入口，避免底栏空白。
  return normalizeTabs(DEFAULT_TAB_LIST);
}

export function buildVisibleTabBarList() {
  const tabs = getModuleEntryTabs();
  return tabs.filter((t) => TAB_ORDER.includes(t.value) && (t.always || t.enabled));
}

export function isModuleEnabled(moduleKey) {
  const tabs = getModuleEntryTabs();
  if (!tabs.length) return false;
  const t = tabs.find((x) => x.value === moduleKey);
  return !!(t && t.enabled !== false);
}

export function getFirstVisibleTabUrl() {
  const visible = buildVisibleTabBarList();
  const first = visible[0] ? visible[0].value : '';
  return first ? `/pages/${first}/index` : '';
}

/**
 * @param {'task'|'errand'|'forum'|'mall'} moduleKey
 * @returns {boolean} 是否已触发跳转（若 true，调用方应跳过后续加载）
 */
export function redirectIfEntryHidden(moduleKey) {
  if (moduleKey === 'my') return false;
  const tabs = getModuleEntryTabs();
  // 配置尚未加载：不做跳转
  if (!tabs.length) return false;
  const target = tabs.find((t) => t.value === moduleKey);
  if (target && target.enabled === false) {
    const url = getFirstVisibleTabUrl();
    if (url) wx.switchTab({ url });
    return true;
  }
  return false;
}

export function readStoredModuleTabs() {
  try {
    const stored = wx.getStorageSync(STORAGE_KEY);
    if (stored && typeof stored === 'object') return stored;
  } catch (e) {}
  return null;
}

export { STORAGE_KEY };

function now() {
  return Date.now();
}

export function cacheGet(key) {
  try {
    const raw = wx.getStorageSync(key);
    if (!raw) return null;
    const item = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (!item) return null;
    if (item.expireAt && now() > item.expireAt) {
      wx.removeStorageSync(key);
      return null;
    }
    return item.data;
  } catch {
    return null;
  }
}

export function cacheSet(key, data, ttlSeconds) {
  try {
    const expireAt = ttlSeconds ? now() + ttlSeconds * 1000 : 0;
    wx.setStorageSync(key, { data, expireAt });
  } catch {}
}

/** 删除本地存储里 key 以 prefix 开头的缓存项（用于发帖/领取后刷新列表等） */
export function invalidateHttpCachePrefix(prefix) {
  const p = String(prefix || '');
  if (!p) return;
  try {
    const keys = (wx.getStorageInfoSync().keys || []).filter((k) => String(k).startsWith(p));
    keys.forEach((k) => {
      try {
        wx.removeStorageSync(k);
      } catch {
        /* ignore */
      }
    });
  } catch {
    /* ignore */
  }
}

// 轻量文本加密/解密（用于配置字符串“避免明文”展示）
// 注意：这是“混淆级别”的对称加密，密钥仍在客户端代码中，不能替代真正的安全防护。

import { CIPHER_KEY } from '~/config/textCipherKey';

function toBytesUtf8(str) {
  const s = unescape(encodeURIComponent(String(str)));
  const bytes = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i += 1) bytes[i] = s.charCodeAt(i);
  return bytes;
}

function fromBytesUtf8(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i += 1) s += String.fromCharCode(bytes[i]);
  return decodeURIComponent(escape(s));
}

function xorBytes(dataBytes, keyBytes) {
  const out = new Uint8Array(dataBytes.length);
  for (let i = 0; i < dataBytes.length; i += 1) {
    out[i] = dataBytes[i] ^ keyBytes[i % keyBytes.length];
  }
  return out;
}

function base64EncodeBytes(bytes) {
  // MiniProgram: wx.arrayBufferToBase64
  // Node: Buffer
  /* eslint-disable no-undef */
  if (typeof wx !== 'undefined' && wx.arrayBufferToBase64) {
    return wx.arrayBufferToBase64(bytes.buffer);
  }
  /* eslint-enable no-undef */
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(bytes).toString('base64');
  }
  // Fallback: btoa (ASCII only)
  let bin = '';
  for (let i = 0; i < bytes.length; i += 1) bin += String.fromCharCode(bytes[i]);
  // eslint-disable-next-line no-undef
  return btoa(bin);
}

function base64DecodeToBytes(b64) {
  /* eslint-disable no-undef */
  if (typeof wx !== 'undefined' && wx.base64ToArrayBuffer) {
    const ab = wx.base64ToArrayBuffer(String(b64));
    return new Uint8Array(ab);
  }
  /* eslint-enable no-undef */
  if (typeof Buffer !== 'undefined') {
    return new Uint8Array(Buffer.from(String(b64), 'base64'));
  }
  // eslint-disable-next-line no-undef
  const bin = atob(String(b64));
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

/**
 * 加密文本，返回 base64 字符串
 * @param {string} plaintext
 * @returns {string}
 */
export function encryptText(plaintext) {
  const keyBytes = toBytesUtf8(CIPHER_KEY);
  const dataBytes = toBytesUtf8(plaintext);
  const out = xorBytes(dataBytes, keyBytes);
  return base64EncodeBytes(out);
}

/**
 * 解密 base64 字符串
 * @param {string} cipherTextBase64
 * @returns {string}
 */
export function decryptText(cipherTextBase64) {
  if (!cipherTextBase64) return '';
  const keyBytes = toBytesUtf8(CIPHER_KEY);
  const dataBytes = base64DecodeToBytes(cipherTextBase64);
  const out = xorBytes(dataBytes, keyBytes);
  return fromBytesUtf8(out);
}
